// @name Handwriting notes
// @background #fffdf7
// @refresh 3600
// A notebook for handwriting with a finger or a stylus: lined, squared,
// dotted or plain paper, a pen, a highlighter that stays under the ink, and
// an eraser that lifts whole strokes. A notebook has pages (back and
// forward turn them, so do the arrows), and every page is saved as its own
// SVG file in the assets folder ("Notes/<notebook> p01.svg", ...), which
// opens as a plain picture anywhere.
//
// How it draws: the page is a canvas (frameos.canvas). A pen stroke is drawn
// into it once, as lines between the points the finger passes. Anything
// that changes what is under the ink (a highlight, an erased stroke, an
// undo) puts back only the box it touched: paper, highlights, the paper's
// lines, then the ink, clipped to the box. The page showing is kept in the
// scene's state (`notebook`, on disk); the other pages are their files.
import { Icon, ICONS, Sheet, SheetBar, Action, FileRow, NameForm, setZoom, z } from './ui'
import {
  safeName, safeFolder, listFiles, writeText, readText, svgRoot, svgElements, numbers, pathRuns, hexColor, xml,
  baseName, stamp,
} from './files'
import { strokeBox, unionBox, boxesMeet, strokeNear, pointCount } from './ink'

const PENS = ['#1f2937', '#1d4ed8', '#b91c1c', '#15803d']
const PEN_NAMES = ['Ink', 'Blue', 'Red', 'Green']
const MARKS = ['#fde68a', '#bbf7d0', '#fbcfe8', '#bfdbfe']
const MARK_NAMES = ['Yellow', 'Green', 'Pink', 'Blue']
const PEN_WIDTHS = [2.5, 4.5] // at 480 px of the page's shorter side
const MARK_WIDTH = 18
const ERASER = 10 // how close to a stroke the eraser lifts it
const STYLES = ['lined', 'grid', 'dotted', 'plain']
const STYLE_NAMES = { lined: 'Lined', grid: 'Squared', dotted: 'Dotted', plain: 'Plain' }
const MAX_POINTS = 6000 // a page's points: the page is kept in state, and drawn again into a fresh canvas

const highContrast = (app) => {
  const mode = app.state.contrast || 'auto'
  return mode === 'high' || (mode === 'auto' && app.frame.color === false)
}

const THEMES = {
  color: {
    paper: '#fffdf7',
    rule: '#bfdbfe',
    margin: '#fca5a5',
    page: 'bg-[#fffdf7] text-slate-800',
    bar: 'bg-[#1e293b] text-white',
    tool: 'text-white active:bg-white/20',
    toolOn: 'bg-sky-300 text-slate-900',
    toolOff: 'text-slate-500',
    pill: 'bg-[#1e293b] text-white',
    panel: 'bg-[#1e293b] text-white',
    swatch: 'border-2 border-white/30',
    swatchOn: 'border-4 border-sky-300',
    cover: 'bg-slate-900/40',
    sheet: 'bg-white text-slate-800',
    sheetBar: 'bg-slate-100',
    ghost: 'active:bg-slate-200',
    muted: 'text-slate-500',
    button: 'bg-slate-100 text-slate-800 active:bg-slate-200',
    primary: 'bg-[#1e293b] text-white active:bg-slate-700',
    danger: 'bg-rose-700 text-white active:bg-rose-800',
    row: 'bg-slate-50 active:bg-slate-100',
    rowOn: 'bg-sky-50 border-2 border-sky-300',
    field: 'bg-slate-100 focus:bg-sky-50',
    accentText: 'text-sky-700',
    list: 'bg-slate-100 text-slate-800',
    chip: 'bg-white text-slate-700 border-2 border-slate-200',
    chipOn: 'bg-sky-100 text-slate-900 border-2 border-sky-400',
    note: 'bg-[#1e293b] text-white',
  },
  high: {
    paper: '#ffffff',
    rule: '#000000',
    margin: '#000000',
    page: 'bg-white text-black',
    bar: 'bg-white text-black border-b-2 border-black',
    tool: 'text-black',
    toolOn: 'bg-black text-white',
    toolOff: 'text-black',
    pill: 'bg-white text-black border-2 border-black',
    panel: 'bg-white text-black border-2 border-black',
    swatch: 'border-2 border-black',
    swatchOn: 'border-4 border-black',
    cover: '',
    sheet: 'bg-white text-black border-4 border-black',
    sheetBar: 'bg-white border-b-2 border-black',
    ghost: '',
    muted: 'text-black',
    button: 'bg-white text-black border-2 border-black',
    primary: 'bg-black text-white',
    danger: 'bg-black text-white',
    row: 'bg-white border-2 border-black',
    rowOn: 'bg-white border-4 border-black',
    field: 'bg-white border-2 border-black',
    accentText: 'text-black',
    list: 'bg-white text-black',
    chip: 'bg-white text-black border-2 border-black',
    chipOn: 'bg-black text-white border-2 border-black',
    note: 'bg-black text-white',
  },
}

// ------------------------------------------------------------------ state

// The notebook open (`notebook`, private, on disk): its name, paper style,
// page size, the page showing and how many there are, that page's strokes
// ([color, width, x0, y0, ...]; a highlight's color starts with "h:"),
// whether that page changed since its file was written, and dates.
let book = null
const loadBook = (app) => {
  const kept = app.state.notebook
  if (kept && typeof kept === 'object' && kept.name && Array.isArray(kept.strokes) && kept.w > 0) return kept
  return null
}
const commit = () => frameos.setState('notebook', book)

// The view (list or page), the tool, what is open: the app's own.
let ui = null
const UI_DEFAULTS = { view: '', tool: 'pen', pen: 0, mark: 0, width: 0, panel: '', draft: '', style: '', asking: '', note: '' }
const loadUi = () => Object.assign({}, UI_DEFAULTS, frameos.recall('ui') || {})
const setUi = (patch) => {
  Object.assign(ui, patch)
  frameos.remember('ui', ui)
}
const note = (text) => setUi({ note: text })

let folder = 'Notes'
let hc = false
let T = THEMES.color

// ------------------------------------------------------------------ files

const pageFile = (name, page) => `${folder}/${name} p${String(page + 1).padStart(2, '0')}.svg`
const INDEX = () => `${folder}/notebooks.json`

// Every notebook in the folder, from its page files: {name: pages}.
const notebooks = () => {
  const found = {}
  for (const path of listFiles(folder, ['.svg'])) {
    const m = /^(.*) p(\d+)\.svg$/i.exec(baseName(path))
    if (m) found[m[1]] = Math.max(found[m[1]] || 0, Number(m[2]))
  }
  return found
}

// When each notebook was made and last written: a small index beside the
// pages, else the first page's own data-created / data-modified.
const readIndex = () => {
  try {
    const parsed = JSON.parse(readText(INDEX()) || '{}')
    return parsed && typeof parsed === 'object' ? parsed : {}
  } catch (e) {
    return {}
  }
}
const writeIndex = (index) => writeText(INDEX(), JSON.stringify(index, null, 1) + '\n')
const touchIndex = (name, pages) => {
  const index = readIndex()
  const now = Date.now()
  const had = index[name] || {}
  index[name] = { created: had.created || book?.created || now, modified: now, pages }
  writeIndex(index)
}

const paperLines = (style, w, h, x0, y0, x1, y1, scale) => {
  // The paper's lines inside a box, in the page's units, as one path (lines)
  // or a list of dots. The rule is gap apart, the first a gap and a half down.
  const gap = Math.round(Math.min(w, h) / 12)
  const lines = []
  const dots = []
  if (style === 'lined' || style === 'grid') {
    for (let y = gap * 1.5; y < h; y += gap) if (y >= y0 - 1 && y <= y1 + 1) lines.push(`M${Math.max(0, x0 - 1)} ${y}H${Math.min(w, x1 + 1)}`)
  }
  if (style === 'grid') {
    for (let x = gap / 2; x < w; x += gap) if (x >= x0 - 1 && x <= x1 + 1) lines.push(`M${x} ${Math.max(0, y0 - 1)}V${Math.min(h, y1 + 1)}`)
  }
  if (style === 'dotted') {
    for (let y = gap * 1.5; y < h; y += gap) {
      if (y < y0 - 2 || y > y1 + 2) continue
      for (let x = gap / 2; x < w; x += gap) if (x >= x0 - 2 && x <= x1 + 2) dots.push(x, y)
    }
  }
  return { lines: lines.join(''), dots, gap }
}

// A page as an SVG file: the paper, the highlights, the paper's lines and
// the ink, a polyline per stroke. data- attributes say what the notebook
// needs to open it again; the paper's lines are marked so they are not read
// back as ink.
const pageText = (page, strokes) => {
  const { w, h, style, name } = book
  const paper = '#fffdf7'
  const { lines, dots, gap } = paperLines(style, w, h, 0, 0, w, h, 1)
  const out = [
    `<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}" data-frameos="notes"` +
      ` data-notebook="${xml(name)}" data-page="${page + 1}" data-paper-style="${style}"` +
      ` data-created="${new Date(book.created || Date.now()).toISOString()}" data-modified="${new Date().toISOString()}">`,
    `<title>${xml(name)}, page ${page + 1}</title>`,
    `<desc>A page of handwritten notes from FrameOS.</desc>`,
    `<rect width="${w}" height="${h}" fill="${paper}" data-layer="paper"/>`,
  ]
  const line = (stroke, color, tool) => {
    if (stroke.length <= 4) return `<circle cx="${stroke[2]}" cy="${stroke[3]}" r="${Number(stroke[1]) / 2}" fill="${color}"${tool}/>`
    const points = []
    for (let i = 2; i + 1 < stroke.length; i += 2) points.push(`${stroke[i]},${stroke[i + 1]}`)
    return `<polyline points="${points.join(' ')}" fill="none" stroke="${color}" stroke-width="${stroke[1]}" stroke-linecap="round" stroke-linejoin="round"${tool}/>`
  }
  for (const stroke of strokes) if (String(stroke[0]).startsWith('h:')) out.push(line(stroke, String(stroke[0]).slice(2), ' data-tool="highlighter"'))
  if (lines) out.push(`<path d="${lines}" fill="none" stroke="#bfdbfe" stroke-width="1" data-layer="paper"/>`)
  if (style === 'lined') out.push(`<path d="M${Math.round(gap * 1.5)} 0V${h}" fill="none" stroke="#fca5a5" stroke-width="1" data-layer="paper"/>`)
  if (dots.length) {
    const d = []
    for (let i = 0; i < dots.length; i += 2) d.push(`M${dots[i] - 1} ${dots[i + 1] - 1}h2v2h-2z`)
    out.push(`<path d="${d.join('')}" fill="#94a3b8" data-layer="paper"/>`)
  }
  for (const stroke of strokes) if (!String(stroke[0]).startsWith('h:')) out.push(line(stroke, stroke[0], ''))
  out.push('</svg>')
  return out.join('\n') + '\n'
}

// A page file back into strokes; anything marked as paper is left out, and
// what the reader does not know (fills, text) is skipped.
const parsePage = (text) => {
  const root = svgRoot(text || '')
  if (!root) return null
  const strokes = []
  const q = (v) => Math.round(v * 2) / 2
  for (const [tag, a] of svgElements(text, ['polyline', 'line', 'path', 'circle'])) {
    if (a['data-layer'] === 'paper') continue
    const mark = a['data-tool'] === 'highlighter'
    if (tag === 'circle') {
      const fill = hexColor(a.fill)
      if (fill && parseFloat(a.r) > 0) strokes.push([(mark ? 'h:' : '') + fill, q(parseFloat(a.r) * 2), q(parseFloat(a.cx) - root.x), q(parseFloat(a.cy) - root.y)])
      continue
    }
    const color = hexColor(a.stroke)
    if (!color) continue
    const width = q(parseFloat(a['stroke-width']) || 1)
    const runs = tag === 'line' ? [[a.x1, a.y1, a.x2, a.y2].map((v) => parseFloat(v || '0'))] : tag === 'path' ? pathRuns(a.d) : [numbers(a.points)]
    for (const run of runs) {
      if (run.length < 2) continue
      const stroke = [(mark ? 'h:' : '') + color, width]
      for (let i = 0; i + 1 < run.length; i += 2) stroke.push(q(run[i] - root.x), q(run[i + 1] - root.y))
      strokes.push(stroke)
    }
  }
  return { w: root.w, h: root.h, style: STYLES.includes(root.attrs['data-paper-style']) ? root.attrs['data-paper-style'] : '', strokes }
}

// The page showing into its file, if it changed.
const savePage = () => {
  if (!book || !book.dirty) return true
  if (!writeText(pageFile(book.name, book.page), pageText(book.page, book.strokes))) {
    note('Could not save: does the scene have the "writes assets folder" permission?')
    return false
  }
  book.dirty = false
  book.modified = Date.now()
  touchIndex(book.name, book.pages)
  commit()
  return true
}

// Another page of the notebook showing: this one saved, that one read.
const goToPage = (page) => {
  if (!book || page < 0 || page >= book.pages || page === book.page) return
  if (!savePage()) return
  const parsed = parsePage(readText(pageFile(book.name, page)))
  book.page = page
  book.strokes = parsed ? parsed.strokes : []
  book.gen = (book.gen || 0) + 1
  frameos.remember('undo', [])
  commit()
}
const addPage = () => {
  if (!savePage()) return
  book.page = book.pages
  book.pages += 1
  book.strokes = []
  book.dirty = true // an empty page is a file too, so the count holds
  book.gen = (book.gen || 0) + 1
  frameos.remember('undo', [])
  savePage()
  commit()
}

const openBook = (name) => {
  if (book && book.name !== name) savePage()
  const pages = notebooks()[name] || 0
  const parsed = parsePage(readText(pageFile(name, 0)))
  if (!parsed) {
    note(`The first page of ${name} could not be read`)
    return
  }
  const index = readIndex()[name] || {}
  book = {
    name, style: parsed.style || 'lined', w: parsed.w, h: parsed.h, page: 0, pages: Math.max(1, pages), strokes: parsed.strokes,
    dirty: false, created: index.created || Date.now(), modified: index.modified || Date.now(), gen: (book?.gen || 0) + 1,
  }
  frameos.remember('undo', [])
  commit()
  setUi({ view: 'page', panel: '', asking: '' })
}

const newBook = (name, style, w, h) => {
  if (book) savePage()
  const taken = notebooks()
  let unique = name
  for (let n = 2; taken[unique]; n++) unique = `${name} ${n}`
  book = { name: unique, style, w, h, page: 0, pages: 1, strokes: [], dirty: true, created: Date.now(), modified: Date.now(), gen: (book?.gen || 0) + 1 }
  frameos.remember('undo', [])
  savePage()
  commit()
  setUi({ view: 'page', panel: '', asking: '', note: `${unique}: a new notebook` })
}

const deleteBook = (name) => {
  const pages = notebooks()[name] || 0
  for (let p = 0; p < pages; p++) frameos.deleteAsset(pageFile(name, p))
  const index = readIndex()
  delete index[name]
  writeIndex(index)
  if (book && book.name === name) {
    book = null
    frameos.setState('notebook', null)
  }
}

// The page showing goes; the pages after it move up one.
const deletePage = () => {
  if (!book) return
  if (book.pages <= 1) {
    book.strokes = []
    book.dirty = true
    book.gen = (book.gen || 0) + 1
    savePage()
    return
  }
  for (let p = book.page + 1; p < book.pages; p++) {
    const text = readText(pageFile(book.name, p))
    if (text !== null) writeText(pageFile(book.name, p - 1), text.replace(/data-page="\d+"/, `data-page="${p}"`).replace(/, page \d+<\/title>/, `, page ${p}</title>`))
  }
  frameos.deleteAsset(pageFile(book.name, book.pages - 1))
  book.pages -= 1
  const page = Math.min(book.page, book.pages - 1)
  const parsed = parsePage(readText(pageFile(book.name, page)))
  book.page = page
  book.strokes = parsed ? parsed.strokes : []
  book.dirty = false
  book.gen = (book.gen || 0) + 1
  touchIndex(book.name, book.pages)
  frameos.remember('undo', [])
  commit()
}

// ------------------------------------------------------------------- view

let PW = 800 // the page area, in the UI's pixels
let PH = 420
let k = 1
let CW = 800
let CH = 420
let s = 1
let ox = 0
let oy = 0
let canvas = null

const fitView = () => {
  s = Math.min(PW / book.w, PH / book.h)
  ox = (PW - book.w * s) / 2
  oy = (PH - book.h * s) / 2
}
const px = (v, o) => v * s * k + o * k
const pageX = (x) => Math.round(((x - ox) / s) * 2) / 2
const pageY = (y) => Math.round(((y - oy) / s) * 2) / 2
const unit = () => Math.min(book.w, book.h) / 480
const isMark = (stroke) => String(stroke[0]).startsWith('h:')

const inkOf = (stroke) => (hc ? '#000000' : String(stroke[0]))
const markOf = (stroke) => (hc ? '#ffffff' : String(stroke[0]).slice(2))

const pointsOf = (stroke) => {
  const out = []
  for (let i = 2; i + 1 < stroke.length; i += 2) out.push(Math.round(px(stroke[i], ox) * 10) / 10, Math.round(px(stroke[i + 1], oy) * 10) / 10)
  return out.join(' ')
}
// A pen stroke as SVG in canvas pixels.
const inkEl = (stroke) => {
  const width = Number(stroke[1]) * s * k
  if (stroke.length <= 4) return <circle cx={px(stroke[2], ox)} cy={px(stroke[3], oy)} r={width / 2} fill={inkOf(stroke)} />
  return <polyline points={pointsOf(stroke)} fill="none" stroke={inkOf(stroke)} strokeWidth={width} strokeLinecap="round" strokeLinejoin="round" />
}
// A highlight: a light band; in high contrast, a band outlined in black.
const markEl = (stroke) => {
  const width = Number(stroke[1]) * s * k
  const one = (color, w) => stroke.length <= 4
    ? <circle cx={px(stroke[2], ox)} cy={px(stroke[3], oy)} r={w / 2} fill={color} />
    : <polyline points={pointsOf(stroke)} fill="none" stroke={color} strokeWidth={w} strokeLinecap="round" strokeLinejoin="round" />
  if (!hc) return one(markOf(stroke), width)
  return <g>{one('#000000', width)}{one('#ffffff', Math.max(1, width - 4 * k))}</g>
}
// The paper's lines inside a box of the canvas.
const paperEl = (x0, y0, x1, y1) => {
  const { lines, dots, gap } = paperLines(book.style, book.w, book.h, (x0 / k - ox) / s, (y0 / k - oy) / s, (x1 / k - ox) / s, (y1 / k - oy) / s, 1)
  const t = `translate(${ox * k} ${oy * k}) scale(${s * k})`
  const r = Math.max(1, 1.3 * k)
  return (
    <g>
      {lines ? <path d={lines} transform={t} fill="none" stroke={T.rule} strokeWidth={1 / s} strokeDasharray={hc ? `${2 / s} ${3 / s}` : undefined} /> : null}
      {book.style === 'lined' ? <path d={`M${Math.round(gap * 1.5)} 0V${book.h}`} transform={t} fill="none" stroke={T.margin} strokeWidth={1 / s} /> : null}
      {dots.length ? (
        <g>
          {Array.from({ length: dots.length / 2 }, (_, i) => (
            <circle cx={px(dots[i * 2], ox)} cy={px(dots[i * 2 + 1], oy)} r={r} fill={hc ? '#000000' : '#94a3b8'} />
          ))}
        </g>
      ) : null}
    </g>
  )
}

// One box of the page (canvas pixels) drawn again, clipped to it: paper,
// highlights, the paper's lines, the ink.
const repaintBox = (x0, y0, x1, y1) => {
  x0 = Math.max(0, Math.floor(x0) - 1)
  y0 = Math.max(0, Math.floor(y0) - 1)
  x1 = Math.min(CW, Math.ceil(x1) + 1)
  y1 = Math.min(CH, Math.ceil(y1) + 1)
  if (x1 <= x0 || y1 <= y0) return
  const box = [(x0 / k - ox) / s, (y0 / k - oy) / s, (x1 / k - ox) / s, (y1 / k - oy) / s]
  const inside = book.strokes.filter((stroke) => boxesMeet(strokeBox(stroke), box))
  frameos.draw(canvas, (
    <g>
      <svg x={x0} y={y0} width={x1 - x0} height={y1 - y0} viewBox={`${x0} ${y0} ${x1 - x0} ${y1 - y0}`}>
        <rect x={x0} y={y0} width={x1 - x0} height={y1 - y0} fill={T.paper} />
        {inside.filter(isMark).map(markEl)}
        {paperEl(x0, y0, x1, y1)}
        {inside.filter((stroke) => !isMark(stroke)).map(inkEl)}
      </svg>
    </g>
  ))
}
const repaint = (box) => repaintBox(px(box[0], ox), px(box[1], oy), px(box[2], ox), px(box[3], oy))
const paintAll = () => {
  frameos.clear(canvas, T.paper)
  frameos.draw(canvas, <g>{book.strokes.filter(isMark).map(markEl)}</g>)
  frameos.draw(canvas, paperEl(0, 0, CW, CH))
  const ink = book.strokes.filter((stroke) => !isMark(stroke))
  for (let i = 0; i < ink.length; i += 60) frameos.draw(canvas, <g>{ink.slice(i, i + 60).map(inkEl)}</g>)
}

// ---------------------------------------------------------------- drawing

// The stroke under the finger, and what the eraser lifted so far, kept
// with remember too so a new interpreter between two moves goes on.
let live = null
const liveStroke = () => live || frameos.recall('live') || null
const setLive = (stroke) => {
  live = stroke
  frameos.remember('live', stroke)
}
const pushUndo = (op) => {
  const ops = frameos.recall('undo') || []
  ops.push(op)
  frameos.remember('undo', ops.slice(-30))
}
const changed = () => {
  book.dirty = true
  commit()
}

// Lift every stroke the eraser touches at (x, y); the boxes they left go
// back to what is under them.
const eraseAt = (x, y) => {
  const reach = ERASER * unit()
  const lifted = []
  let box = null
  for (let i = book.strokes.length - 1; i >= 0; i--) {
    const stroke = book.strokes[i]
    const b = strokeBox(stroke)
    if (x < b[0] - reach || x > b[2] + reach || y < b[1] - reach || y > b[3] + reach) continue
    if (strokeNear(stroke, x, y, reach)) {
      lifted.push([i, stroke])
      box = unionBox(box, b)
      book.strokes.splice(i, 1)
    }
  }
  if (!lifted.length) return
  const erased = frameos.recall('erased') || []
  for (const item of lifted) erased.push(item)
  frameos.remember('erased', erased)
  repaint(box)
  changed() // in state at once: the next render reads the page from there
}

const startStroke = (e) => {
  if (ui.panel || ui.note) {
    const hadPanel = ui.panel
    setUi({ panel: '', note: '' })
    if (hadPanel) return
  }
  const x = pageX(e.localX)
  const y = pageY(e.localY)
  if (ui.tool === 'eraser') {
    frameos.remember('erased', [])
    setLive(['eraser', 0, x, y])
    eraseAt(x, y)
    return
  }
  if (pointCount(book.strokes) >= MAX_POINTS) {
    note('This page is full: turn to a new one')
    return
  }
  const mark = ui.tool === 'mark'
  const stroke = mark
    ? ['h:' + MARKS[ui.mark], Math.round(MARK_WIDTH * unit() * 10) / 10, x, y]
    : [PENS[ui.pen], Math.round(PEN_WIDTHS[ui.width] * unit() * 10) / 10, x, y]
  setLive(stroke)
  frameos.draw(canvas, mark ? markEl(stroke) : inkEl(stroke))
}
const moveStroke = (e) => {
  const stroke = liveStroke()
  if (!stroke || !canvas) return
  const x = pageX(e.localX)
  const y = pageY(e.localY)
  if (stroke[0] === 'eraser') {
    // Along the way from the last point, not only at the new one: a quick
    // swipe across a word lifts it too.
    const lx = stroke[2] as number
    const ly = stroke[3] as number
    const steps = Math.min(40, Math.ceil(Math.hypot(x - lx, y - ly) / ((ERASER * unit()) / 2)))
    for (let i = 1; i <= steps; i++) eraseAt(lx + ((x - lx) * i) / steps, ly + ((y - ly) * i) / steps)
    setLive(['eraser', 0, x, y])
    return
  }
  const lx = stroke[stroke.length - 2] as number
  const ly = stroke[stroke.length - 1] as number
  if (Math.abs(x - lx) + Math.abs(y - ly) < 1.5) return
  const piece = [stroke[0], stroke[1], lx, ly, x, y]
  frameos.draw(canvas, isMark(piece) ? markEl(piece) : inkEl(piece))
  stroke.push(x, y)
  setLive(stroke)
}
const endStroke = () => {
  const stroke = liveStroke()
  if (!stroke) return
  setLive(null)
  if (stroke[0] === 'eraser') {
    const erased = frameos.recall('erased') || []
    frameos.remember('erased', [])
    if (erased.length) {
      pushUndo({ erased })
      changed()
    }
    return
  }
  book.strokes.push(stroke)
  pushUndo({ added: 1 })
  // A highlight goes under the ink and the paper's lines: its box again.
  if (isMark(stroke)) repaint(strokeBox(stroke))
  changed()
}

const undo = () => {
  const ops = frameos.recall('undo') || []
  const op = ops.pop()
  if (!op || !book) return
  frameos.remember('undo', ops)
  let box = null
  if (op.added && book.strokes.length) {
    box = strokeBox(book.strokes.pop())
  } else if (op.erased) {
    // Put them back where they were, the lowest index first.
    const items = op.erased.slice().sort((a, b) => a[0] - b[0])
    for (const [i, stroke] of items) {
      book.strokes.splice(Math.min(i, book.strokes.length), 0, stroke)
      box = unionBox(box, strokeBox(stroke))
    }
  }
  if (box && canvas) repaint(box)
  else if (box) book.gen = (book.gen || 0) + 1
  changed()
}

// ----------------------------------------------------------------- pieces

const Tool = ({ b, d, on, off, onClick, children }) => (
  <div className={`w-[${b}px] h-[${b}px] shrink-0 flex items-center justify-center rounded-[${z(12)}px] ${on ? T.toolOn : off ? T.toolOff : T.tool}`}
    onClick={onClick}>
    {children || <Icon d={d} className={`w-[${Math.round(b * 0.5)}px] h-[${Math.round(b * 0.5)}px]`} />}
  </div>
)

const Bar = memo(({ b, wide, name, page, pages, tool, pen, mark, canUndo, dirty, hcLook }) => (
  <div className={`flex items-center gap-[${z(4)}px] h-[${b + z(8)}px] px-[${z(6)}px] ${T.bar}`} onPointerDown={() => {}}>
    <Tool b={b} d={ICONS.menu} onClick={() => {
      savePage()
      setUi({ view: 'list', panel: '', asking: '' })
    }} />
    <div className="flex-1 flex flex-col min-w-0 px-[4px]" onClick={() => setUi({ panel: ui.panel === 'book' ? '' : 'book', asking: '' })}>
      <span className={`text-[${z(18)}px] font-bold truncate`}>{name}</span>
      {wide ? <span className={`text-[${z(13)}px] truncate opacity-70`}>{`Page ${page + 1} of ${pages}${dirty ? ' · not saved yet' : ''}`}</span> : null}
    </div>
    <Tool b={b} on={tool === 'pen'} onClick={() => setUi({ tool: 'pen', panel: tool === 'pen' && ui.panel !== 'pens' ? 'pens' : '' })}>
      <Icon d={ICONS.pencil} className={`w-[${Math.round(b * 0.5)}px] h-[${Math.round(b * 0.5)}px] ${tool === 'pen' || hcLook ? '' : `text-[${PENS[pen] === '#1f2937' ? '#ffffff' : PENS[pen]}]`}`} />
    </Tool>
    <Tool b={b} on={tool === 'mark'} onClick={() => setUi({ tool: 'mark', panel: tool === 'mark' && ui.panel !== 'marks' ? 'marks' : '' })}>
      <Icon d={ICONS.marker} className={`w-[${Math.round(b * 0.5)}px] h-[${Math.round(b * 0.5)}px] ${tool === 'mark' || hcLook ? '' : `text-[${MARKS[mark]}]`}`} />
    </Tool>
    <Tool b={b} d={ICONS.eraser} on={tool === 'eraser'} onClick={() => setUi({ tool: 'eraser', panel: '' })} />
    <Tool b={b} d={ICONS.undo} off={!canUndo} onClick={undo} />
    {dirty ? (
      <Tool b={b} d={ICONS.save} onClick={() => {
        if (savePage()) note(`Saved ${pageFile(book.name, book.page)}`)
      }} />
    ) : (
      <Tool b={b} d={ICONS.check} off={true} onClick={() => note(`Page ${book.page + 1} is saved in ${pageFile(book.name, book.page)}`)} />
    )}
  </div>
))

// Page turning, at the bottom right of the page.
const Pager = ({ b, page, pages }) => (
  <div className={`flex items-center gap-[${z(4)}px] p-[${z(4)}px] rounded-[${z(16)}px] ${T.pill}`} onPointerDown={() => {}}>
    <Tool b={b} d={ICONS.left} off={page === 0} onClick={() => goToPage(page - 1)} />
    <span className={`text-[${z(16)}px] font-semibold px-[${z(4)}px]`}>{`${page + 1} / ${pages}`}</span>
    <Tool b={b} d={ICONS.right} off={page >= pages - 1} onClick={() => goToPage(page + 1)} />
    <Tool b={b} d={ICONS.plus} onClick={addPage} />
  </div>
)

// Colors (and the pen's two widths) under the bar.
const Swatches = ({ b, x, list, names, chosen, onPick, widths }) => {
  const sw = Math.round(b * 0.8)
  return (
    <div className={`absolute top-[${b + z(8) + z(6)}px] left-[${x}px] flex flex-col gap-[${z(10)}px] p-[${z(12)}px] rounded-[${z(16)}px] ${T.panel}`} onPointerDown={() => {}}>
      {hc ? <span className={`text-[${z(14)}px]`}>{widths ? 'Black ink' : 'Highlights: an outlined band'}</span> : (
        <div className="flex gap-[8px]">
          {list.map((color, i) => (
            <div className={`w-[${sw}px] h-[${sw}px] rounded-full bg-[${color}] ${chosen === i ? T.swatchOn : T.swatch}`} onClick={() => onPick(i)} />
          ))}
        </div>
      )}
      {widths ? (
        <div className="flex gap-[8px]">
          {PEN_WIDTHS.map((w, i) => (
            <div className={`h-[${sw}px] px-[${z(12)}px] flex items-center gap-[${z(8)}px] rounded-[${z(12)}px] ${ui.width === i ? T.toolOn : T.tool}`}
              onClick={() => setUi({ width: i, panel: '' })}>
              <div className={`w-[${z(24)}px] h-[${Math.round(w * 1.4)}px] rounded-full ${ui.width === i ? (hc ? 'bg-white' : 'bg-slate-900') : hc ? 'bg-black' : 'bg-white'}`} />
              <span className={`text-[${z(14)}px]`}>{i === 0 ? 'Fine' : 'Bold'}</span>
            </div>
          ))}
        </div>
      ) : null}
      {!hc ? <span className={`text-[${z(14)}px]`}>{names[chosen]}</span> : null}
    </div>
  )
}

// ----------------------------------------------------------------- sheets

const StyleChips = ({ value, onPick }) => (
  <div className="grid grid-cols-4 gap-[8px]">
    {STYLES.map((style) => (
      <div className={`flex items-center justify-center h-[${z(52)}px] rounded-[${z(12)}px] text-[${z(16)}px] ${value === style ? T.chipOn : T.chip}`}
        onClick={() => onPick(style)}>
        {STYLE_NAMES[style]}
      </div>
    ))}
  </div>
)

// The notebook's own sheet: its paper, its dates, deleting this page.
const BookSheet = ({ w }) => {
  const close = () => setUi({ panel: '', asking: '' })
  if (ui.asking === 'page') {
    return (
      <Sheet t={{ ...T, bar: T.sheetBar }} w={w} onClose={close}>
        <SheetBar t={{ ...T, bar: T.sheetBar }} title={`Delete page ${book.page + 1}?`} sub={pageFile(book.name, book.page)} onClose={close} />
        <div className={`flex gap-[${z(12)}px] p-[${z(16)}px]`}>
          <div className="flex-1"><Action t={T} label="Keep it" onClick={() => setUi({ asking: '' })} /></div>
          <div className="flex-1"><Action t={T} kind="danger" d={ICONS.bin} label="Delete" onClick={() => {
            deletePage()
            setUi({ panel: '', asking: '', note: 'Page deleted' })
          }} /></div>
        </div>
      </Sheet>
    )
  }
  return (
    <Sheet t={T} w={w} onClose={close}>
      <SheetBar t={{ ...T, bar: T.sheetBar }} title={book.name} sub={`${book.pages} ${book.pages === 1 ? 'page' : 'pages'} · started ${stamp(book.created || Date.now())}`} onClose={close} />
      <div className={`flex flex-col gap-[${z(12)}px] p-[${z(16)}px]`}>
        <span className={`text-[${z(14)}px] ${T.muted}`}>Paper</span>
        <StyleChips value={book.style} onPick={(style) => {
          book.style = style
          book.dirty = true
          book.gen = (book.gen || 0) + 1
          commit()
        }} />
        <div className={`flex gap-[${z(12)}px]`}>
          <div className="flex-1"><Action t={T} d={ICONS.plus} label="New page" onClick={() => {
            addPage()
            setUi({ panel: '' })
          }} /></div>
          <div className="flex-1"><Action t={T} d={ICONS.bin} label="Delete page…" onClick={() => setUi({ asking: 'page' })} /></div>
        </div>
      </div>
    </Sheet>
  )
}

// A new notebook: its name and its paper.
const NewSheet = ({ w, defaultStyle }) => {
  const close = () => setUi({ panel: '', asking: '' })
  const style = ui.style || defaultStyle
  const create = () => {
    const name = safeName(ui.draft)
    if (!name) {
      note('Give the notebook a name')
      return
    }
    newBook(name, style, PW, PH)
  }
  return (
    <Sheet t={T} w={w} onClose={close}>
      <SheetBar t={{ ...T, bar: T.sheetBar }} title="A new notebook" sub={`Its pages go in ${folder}/`} onClose={close} />
      <div className={`flex flex-col gap-[${z(12)}px] p-[${z(16)}px]`}>
        <NameForm t={T} value={ui.draft} placeholder="Name" label="Start" onChange={(v) => setUi({ draft: v })} onSave={create} />
        <StyleChips value={style} onPick={(pick) => setUi({ style: pick })} />
      </div>
    </Sheet>
  )
}

// Every notebook, newest first, with its pages and when it was written.
const ListView = ({ W, H, defaultStyle }) => {
  const found = notebooks()
  const index = readIndex()
  const names = Object.keys(found)
  const dates = {}
  for (const name of names) {
    let when = index[name]?.modified
    if (!when) {
      // No index entry (copied in from elsewhere): the first page's own date.
      const head = readText(pageFile(name, 0), 700) || ''
      const m = /data-modified="([^"]+)"/.exec(head)
      when = m ? Date.parse(m[1]) : 0
    }
    dates[name] = when || 0
  }
  names.sort((a, b) => dates[b] - dates[a] || a.localeCompare(b))
  const w = Math.min(W - 24, z(560))
  const draft = () => `Notes ${stamp(Date.now()).slice(0, 10)}`
  return (
    <div className={`flex flex-col w-[${W}px] h-[${H}px] ${T.list}`}>
      <div className={`flex items-center gap-[${z(8)}px] h-[${z(64)}px] px-[${z(16)}px] ${T.bar}`}>
        <Icon d={ICONS.file} className={`w-[${z(28)}px] h-[${z(28)}px]`} />
        <span className={`flex-1 text-[${z(22)}px] font-bold truncate`}>Notes</span>
        {book ? (
          <div className={`h-[${z(48)}px] px-[${z(14)}px] flex items-center rounded-[${z(12)}px] text-[${z(16)}px] ${T.tool}`} onClick={() => setUi({ view: 'page' })}>
            Back to the page
          </div>
        ) : null}
        <div className={`h-[${z(48)}px] px-[${z(14)}px] flex items-center gap-[${z(6)}px] rounded-[${z(12)}px] text-[${z(16)}px] font-bold ${T.toolOn}`}
          onClick={() => setUi({ panel: 'new', draft: draft(), style: '' })}>
          <Icon d={ICONS.plus} className={`w-[${z(22)}px] h-[${z(22)}px]`} />
          New
        </div>
      </div>
      <div className={`flex-1 overflow-y-auto p-[${z(12)}px]`}>
        <div className={`flex flex-col gap-[${z(8)}px] w-[${Math.min(W - z(24), z(720))}px] mx-auto`}>
          {names.length === 0 ? (
            <span className={`p-[${z(12)}px] text-[${z(18)}px] ${T.muted}`}>{`No notebooks in ${folder} yet. Tap New to start one.`}</span>
          ) : null}
          {names.map((name) => (
            <FileRow t={book && book.name === name ? { ...T, row: T.rowOn } : T} d={ICONS.file} name={name}
              sub={`${found[name]} ${found[name] === 1 ? 'page' : 'pages'}${dates[name] ? ` · ${stamp(dates[name])}` : ''}`}
              asking={ui.asking === name}
              onOpen={() => openBook(name)}
              onAsk={() => setUi({ asking: name })}
              onCancel={() => setUi({ asking: '' })}
              onDelete={() => {
                deleteBook(name)
                setUi({ asking: '', note: `Deleted ${name}` })
              }} />
          ))}
        </div>
      </div>
      {ui.note ? (
        <div className={`absolute bottom-[${z(16)}px] left-0 right-0 flex justify-center`}>
          <div className={`px-[${z(16)}px] py-[${z(8)}px] rounded-[${z(12)}px] text-[${z(16)}px] ${T.note}`} onClick={() => setUi({ note: '' })}>{ui.note}</div>
        </div>
      ) : null}
      {ui.panel === 'new' ? <NewSheet w={w} defaultStyle={defaultStyle} /> : null}
    </div>
  )
}

// -------------------------------------------------------------------- get

export function get(app, context) {
  const W = Math.round(context.imageWidth ?? app.frame.width)
  const H = Math.round(context.imageHeight ?? app.frame.height)
  hc = highContrast(app)
  T = hc ? THEMES.high : THEMES.color
  setZoom(Math.max(1, Math.min(2, Math.min(W, H) / 480)))
  folder = safeFolder(app.state.folder, 'Notes')
  const defaultStyle = STYLES.includes(app.state.paper) ? app.state.paper : 'lined'
  book = loadBook(app)
  ui = loadUi()
  live = frameos.recall('live') || null

  const b = Math.max(44, Math.min(96, Math.round(Math.min(W, H) * 0.105)))
  const barH = b + z(8)
  PW = W
  PH = H - barH

  // The first time, with no notebook anywhere: a page to write on at once,
  // in state only until something is written on it.
  if (!book && !ui.view && Object.keys(notebooks()).length === 0) {
    book = { name: 'My notes', style: defaultStyle, w: PW, h: PH, page: 0, pages: 1, strokes: [], dirty: false, created: Date.now(), modified: Date.now(), gen: 1 }
    commit()
  }
  if (!book || ui.view === 'list') {
    if (!book && ui.view !== 'list') ui.view = 'list'
    return <ListView W={W} H={H} defaultStyle={defaultStyle} />
  }

  k = Math.max(1, Math.min(4, app.frame.scale || 1))
  if (PW * k * PH * k > 4096 * 4096) k = 1
  CW = Math.round(PW * k)
  CH = Math.round(PH * k)
  fitView()
  canvas = frameos.canvas('page', CW, CH, T.paper)
  if (!canvas) {
    return <div className="flex items-center justify-center w-full h-full p-8 bg-white text-black text-2xl">Not enough memory for a page this size.</div>
  }
  const look = [hc, book.name, book.page, book.style, CW, CH, book.w, book.h, book.gen].join('|')
  if (canvas.fresh || frameos.recall('look') !== look) {
    paintAll()
    frameos.remember('look', look)
  }

  const wide = W >= 560
  const canUndo = (frameos.recall('undo') || []).length > 0
  const swatchX = Math.max(8, W - z(6) - b * 5 - z(4) * 4 - z(12) * 2 - Math.round(b * 0.8) * 4 - 24)
  return (
    <div className={`flex flex-col w-[${W}px] h-[${H}px] ${T.page}`}>
      <Bar b={b} wide={wide} name={book.name} page={book.page} pages={book.pages} tool={ui.tool} pen={ui.pen} mark={ui.mark}
        canUndo={canUndo} dirty={!!book.dirty} hcLook={hc} />
      <img className={`w-[${PW}px] h-[${PH}px]`} src={canvas}
        onPointerDown={startStroke} onPointerMove={moveStroke} onPointerUp={endStroke} />
      <div className={`absolute right-[${z(10)}px] bottom-[${z(10)}px]`}>
        <Pager b={Math.round(b * 0.85)} page={book.page} pages={book.pages} />
      </div>
      {ui.panel === 'pens' ? (
        <Swatches b={b} x={swatchX} list={PENS} names={PEN_NAMES} chosen={ui.pen} widths={true}
          onPick={(i) => setUi({ pen: i, tool: 'pen', panel: '' })} />
      ) : null}
      {ui.panel === 'marks' ? (
        <Swatches b={b} x={swatchX} list={MARKS} names={MARK_NAMES} chosen={ui.mark} widths={false}
          onPick={(i) => setUi({ mark: i, tool: 'mark', panel: '' })} />
      ) : null}
      {ui.note && !ui.panel ? (
        <div className={`absolute top-[${barH + z(10)}px] left-0 right-0 flex justify-center`}>
          <div className={`px-[${z(16)}px] py-[${z(8)}px] rounded-[${z(12)}px] text-[${z(16)}px] max-w-[${Math.round(W * 0.8)}px] ${T.note}`}
            onPointerDown={() => {}} onClick={() => setUi({ note: '' })}>{ui.note}</div>
        </div>
      ) : null}
      {ui.panel === 'book' ? <BookSheet w={Math.min(W - 24, z(560))} /> : null}
    </div>
  )
}

// back and forward turn the pages (a swipe in from the edge on a touch
// screen, or the frame's buttons); Ctrl+Z undoes on a keyboard.
export function onEvent(app, context) {
  if (!book) book = loadBook(app)
  if (!ui) ui = loadUi()
  if (!book || ui.view === 'list') return false
  if (context.event === 'back') {
    goToPage(book.page - 1)
    return true
  }
  if (context.event === 'forward') {
    goToPage(book.page + 1)
    return true
  }
  if (context.event === 'keyDown' && context.payload?.ctrl && String(context.payload?.key || '').toLowerCase() === 'z') {
    undo()
    return true
  }
  return false
}

