// Small pieces of UI the scene's panels share: an icon, a sheet over the
// page, a row of a list, a button. Each takes the classes of the look in use,
// and is sized for a finger at 480 px of the shorter side, larger on a big
// screen (setZoom, once per render).

let Z = 1
export const setZoom = (zoom: number) => {
  Z = zoom
}
// A length in pixels at this zoom.
export const z = (n: number): number => Math.round(n * Z)

export const Icon = ({ d, className }) => (
  <svg className={className} viewBox="0 0 24 24">
    <path d={d} fill="currentColor" />
  </svg>
)

// Material Design Icons paths (24 x 24, filled).
export const ICONS = {
  undo: 'M12.5,8C9.85,8 7.45,9 5.6,10.6L2,7V16H11L7.38,12.38C8.77,11.22 10.54,10.5 12.5,10.5C16.04,10.5 19.05,12.81 20.1,16L22.47,15.22C21.08,11.03 17.15,8 12.5,8Z',
  eraser: 'M16.24,3.56L21.19,8.5C21.97,9.29 21.97,10.55 21.19,11.34L12,20.53C10.44,22.09 7.91,22.09 6.34,20.53L2.81,17C2.03,16.21 2.03,14.95 2.81,14.16L13.41,3.56C14.2,2.78 15.46,2.78 16.24,3.56M4.22,15.58L7.76,19.11C8.54,19.9 9.8,19.9 10.59,19.11L14.12,15.58L9.17,10.63L4.22,15.58Z',
  pencil: 'M20.71,7.04C21.1,6.65 21.1,6 20.71,5.63L18.37,3.29C18,2.9 17.35,2.9 16.96,3.29L15.12,5.12L18.87,8.87M3,17.25V21H6.75L17.81,9.93L14.06,6.18L3,17.25Z',
  marker: 'M14,3L21,10L12.5,18.5H7.5V13.5L14,3M3,20H15V22H3V20Z',
  menu: 'M3,6H21V8H3V6M3,11H21V13H3V11M3,16H21V18H3V16Z',
  save: 'M15,9H5V5H15M12,19A3,3 0 0,1 9,16A3,3 0 0,1 12,13A3,3 0 0,1 15,16A3,3 0 0,1 12,19M17,3H5C3.89,3 3,3.9 3,5V19A2,2 0 0,0 5,21H19A2,2 0 0,0 21,19V7L17,3Z',
  plus: 'M19,13H13V19H11V13H5V11H11V5H13V11H19V13Z',
  bin: 'M19,4H15.5L14.5,3H9.5L8.5,4H5V6H19M6,19A2,2 0 0,0 8,21H16A2,2 0 0,0 18,19V7H6V19Z',
  close: 'M19,6.41L17.59,5L12,10.59L6.41,5L5,6.41L10.59,12L5,17.59L6.41,19L12,13.41L17.59,19L19,17.59L13.41,12L19,6.41Z',
  file: 'M13,9V3.5L18.5,9M6,2C4.89,2 4,2.89 4,4V20A2,2 0 0,0 6,22H18A2,2 0 0,0 20,20V8L14,2H6Z',
  left: 'M15.41,16.58L10.83,12L15.41,7.41L14,6L8,12L14,18L15.41,16.58Z',
  right: 'M8.59,16.58L13.17,12L8.59,7.41L10,6L16,12L10,18L8.59,16.58Z',
  check: 'M21,7L9,19L3.5,13.5L4.91,12.09L9,16.17L19.59,5.59L21,7Z',
}

// A sheet over the page: a cover that closes it on a tap (and takes the
// press, so nothing under it draws), and a card in the middle.
export const Sheet = ({ t, w, h, onClose, children }) => (
  <div className={`absolute inset-0 flex items-center justify-center ${t.cover}`}
    onPointerDown={() => {}} onClick={onClose}>
    <div className={`flex flex-col w-[${w}px] ${h ? `h-[${h}px]` : ''} rounded-[${z(16)}px] overflow-hidden ${t.sheet}`}
      onPointerDown={() => {}} onClick={() => {}}>
      {children}
    </div>
  </div>
)

const Square = ({ t, d, onClick }) => (
  <div className={`w-[${z(48)}px] h-[${z(48)}px] shrink-0 flex items-center justify-center rounded-[${z(12)}px] ${t.ghost}`} onClick={onClick}>
    <Icon d={d} className={`w-[${z(28)}px] h-[${z(28)}px]`} />
  </div>
)

// A sheet's title bar: a title and a close button.
export const SheetBar = ({ t, title, sub, onBack, onClose }) => (
  <div className={`flex items-center gap-[${z(8)}px] h-[${z(64)}px] shrink-0 px-[${z(8)}px] ${t.bar}`}>
    {onBack ? <Square t={t} d={ICONS.left} onClick={onBack} /> : <div className={`w-[${z(8)}px]`} />}
    <div className="flex-1 flex flex-col min-w-0">
      <span className={`text-[${z(20)}px] font-bold truncate`}>{title}</span>
      {sub ? <span className={`text-[${z(14)}px] truncate ${t.muted}`}>{sub}</span> : null}
    </div>
    <Square t={t} d={ICONS.close} onClick={onClose} />
  </div>
)

// A button with an icon and a word, as wide as its row allows.
export const Action = ({ t, d, label, onClick, kind }) => (
  <div className={`flex items-center gap-[${z(12)}px] h-[${z(56)}px] px-[${z(16)}px] rounded-[${z(12)}px] ${kind === 'primary' ? t.primary : kind === 'danger' ? t.danger : t.button}`}
    onClick={onClick}>
    {d ? <Icon d={d} className={`w-[${z(24)}px] h-[${z(24)}px] shrink-0`} /> : null}
    <span className={`text-[${z(18)}px] font-semibold truncate`}>{label}</span>
  </div>
)

// A file in a list: tap to open, the bin asks before it deletes.
export const FileRow = ({ t, d, name, sub, asking, onOpen, onAsk, onDelete, onCancel }) =>
  asking ? (
    <div className={`flex items-center gap-[${z(8)}px] h-[${z(64)}px] px-[${z(12)}px] rounded-[${z(12)}px] ${t.row}`}>
      <span className={`flex-1 text-[${z(18)}px] truncate`}>{`Delete "${name}"?`}</span>
      <div className={`h-[${z(48)}px] px-[${z(16)}px] flex items-center rounded-[${z(12)}px] text-[${z(18)}px] ${t.button}`} onClick={onCancel}>Keep</div>
      <div className={`h-[${z(48)}px] px-[${z(16)}px] flex items-center rounded-[${z(12)}px] text-[${z(18)}px] font-bold ${t.danger}`} onClick={onDelete}>Delete</div>
    </div>
  ) : (
    <div className={`flex items-center gap-[${z(12)}px] h-[${z(64)}px] pl-[${z(12)}px] pr-[${z(4)}px] rounded-[${z(12)}px] ${t.row}`}>
      <div className={`flex-1 flex items-center gap-[${z(12)}px] h-[${z(64)}px] min-w-0`} onClick={onOpen}>
        <Icon d={d} className={`w-[${z(28)}px] h-[${z(28)}px] shrink-0 ${t.accentText}`} />
        <div className="flex-1 flex flex-col min-w-0">
          <span className={`text-[${z(18)}px] truncate`}>{name}</span>
          {sub ? <span className={`text-[${z(14)}px] truncate ${t.muted}`}>{sub}</span> : null}
        </div>
      </div>
      {onAsk ? (
        <div className={`w-[${z(48)}px] h-[${z(48)}px] shrink-0 flex items-center justify-center rounded-[${z(12)}px] ${t.ghost}`} onClick={onAsk}>
          <Icon d={ICONS.bin} className={`w-[${z(24)}px] h-[${z(24)}px] ${t.muted}`} />
        </div>
      ) : null}
    </div>
  )

// A name to save under, with the keyboard; Enter saves.
export const NameForm = ({ t, value, placeholder, label, onChange, onSave }) => (
  <div className={`flex items-center gap-[${z(8)}px]`}>
    <input className={`flex-1 h-[${z(56)}px] px-[${z(16)}px] rounded-[${z(12)}px] text-[${z(18)}px] ${t.field}`} value={value} placeholder={placeholder}
      onChange={(e) => onChange(e.target.value)}
      onKeyDown={(e) => { if (e.key === 'Enter') onSave() }} />
    <div className={`h-[${z(56)}px] px-[${z(20)}px] flex items-center rounded-[${z(12)}px] text-[${z(18)}px] font-bold ${t.primary}`} onClick={onSave}>{label}</div>
  </div>
)
